slides=[]
def s(key,title,subtitle,body='',image=None,section='story',kind='split',points=None,situation='concept'):
    slides.append(dict(key=key,title=title,subtitle=subtitle,body=body,image=image,section=section,kind=kind,points=points or [],situation=situation))
s('cover','Haus\nMorgenlicht.','AN OLD CHALET. A NEW WAY TO LIVE.','Air, light and the mountains. A fictional Austrian chalet conversion / September 2026',image='summer',kind='cover')
s('invitation','A new chapter,\nwith an old soul.','01 / THE INVITATION','For fictional clients Anna and Lukas Leitner, the chalet becomes a generous retreat in every season: open to summer meadows, warm against winter snow, and always connected to the mountains.',image='summer',points=['Imagined location: the Tyrolean Alps, Austria','Illustrative 280 m² interior concept across three levels','Demo 03 / Chalet conversion'])
s('mountains','Leave room\nfor the view.','THE FEELING','Morning air. A clear horizon. The quiet of the mountains before the day begins. The design brings that sense of space indoors through light, calm materials and carefully framed views.',image='mountains',kind='hero',situation='reference')
s('original','A house worth\nkeeping.','02 / THE IMAGINED ORIGINAL','A weathered timber chalet with a generous pitched roof, a stone base and a heavy carved balcony. Its character is the starting point. This is an AI-generated fictional existing-condition study, not a site survey photograph.',image='before-exterior',section='current',situation='before')
s('beforeliving','Warm character.\nClosed-off rooms.','THE ORIGINAL INTERIOR','Dark beams, orange-toned panelling, compact windows and substantial furniture make the imagined living room feel inward-looking. The green tiled stove is a beautiful anchor for its next chapter.',image='before-living',section='current',situation='before')
s('keepchange','Keep the soul.\nOpen the possibilities.','THE CONVERSION STRATEGY','Retain the elements that give the chalet its identity. Introduce contemporary comfort through deliberate, local changes.',section='current',kind='principles',points=['Keep the roof silhouette, stone plinth and sound beams','Restore the tiled stove and selected weathered timber','Open the valley facade and selected internal partitions','Lighten the envelope with pale fir and warm plaster'])
s('exteriorcompare','Same silhouette.\nNew light.','BEFORE / PROPOSED EXTERIOR','A matched concept edit keeps the camera position, roof geometry and landscape recognisable while exploring a lighter facade, simpler balcony and larger view openings. Both images are fictional generated studies.',section='designs',kind='comparison')
s('materials','Mountain materials.\nA lighter touch.','03 / MATERIAL MOOD','Weathered old timber meets pale silver fir, warm ivory plaster and cool grey-green stone. Brushed metal provides a quiet line of detail. Texture does the work that ornament once did.',image='materials',section='moodboards',kind='board')
s('textiles','The warmth\nyou can feel.','TEXTILE & COLOUR MOOD','Ivory wool, oatmeal linen, glacier blue and a small rust accent. Softness belongs to the interior; the mountain view brings all the drama we need.',image='textiles',section='moodboards',kind='board')
s('palette','Snow. Stone.\nSky. Timber.','THE COLOUR LANGUAGE','A fresh, pale foundation with mineral blues and the warmth of timber. Existing dark beams remain deliberate lines within the lighter rooms.',section='moodboards',kind='palette')
s('existingplan','Understand the\noriginal rhythm.','04 / EXISTING LAYOUT STUDY','An imagined main-floor arrangement of separate kitchen, dining, living and arrival rooms. The plan is a storytelling device based on the fictional brief; it is not an existing measured drawing.',image='existing-plan',section='current',kind='plan',situation='before')
s('proposedplan','Open the rooms.\nKeep the refuge.','PROPOSED MAIN FLOOR','Connected cooking, dining and living face the valley, while storage, stairs and practical arrival functions stay contained. Enlarged openings and partition changes require site-specific structural design.',image='proposed-plan',section='designs',kind='plan')
s('living','The mountains,\ninvited inside.','THE REIMAGINED LIVING ROOM','The original beam rhythm and green tiled stove remain. Pale surfaces, softer furniture and a larger valley-facing opening make the same room feel open, generous and full of air.',image='living',section='designs',kind='hero')
s('interiorcompare','The same room.\nA different feeling.','BEFORE / PROPOSED LIVING','A matched interior edit retains the camera, room boundaries, beams and stove. The transformation comes from daylight, restrained joinery and furniture that allows the space to breathe.',section='designs',kind='comparison')
s('section','Light follows\nthe roofline.','SECTION / THE SPATIAL IDEA','Retain the pitched roof and work with its volume. New view openings and lighter ceiling infill bring daylight deeper into the chalet; the garden level holds service space and an optional wellness retreat.',image='section',section='designs',kind='plan')
s('kitchen','Breakfast,\nwith a horizon.','KITCHEN & DINING','Pale silver-fir cabinetry, a mineral stone island and an unhurried dining table create the social heart. Old dark beams keep the room grounded in the original chalet.',image='kitchen',section='designs',kind='hero')
s('details','Fewer materials.\nMore meaning.','DETAILS & SPECIFICATION','Joinery, plaster and stone repeat through the house. Every material meets an older element somewhere, making the conversion feel connected rather than newly assembled.',section='designs',kind='details')
s('bedroom','Wake up\nabove the noise.','THE PRIMARY SUITE','A light-filled room beneath the gable, with wool, soft blue and a view of winter peaks. Retained beams frame the pitched ceiling; the new glazing makes the landscape part of the room.',image='bedroom',section='designs',kind='hero')
s('upperplan','Quiet rooms,\nunder the eaves.','UPPER FLOOR CONCEPT','A primary suite, guest room and shared landing are organised around the existing roof form. Gable openings, headroom and escape arrangements remain subject to measured and technical review.',image='upper-plan',section='designs',kind='plan')
s('arrival','For snowy boots\nand muddy adventures.','THE PRACTICAL ARRIVAL','Pale built-in storage, a soft bench and durable mineral flooring make coming home easy. A calm place to leave skis, walking boots and the weather before entering the living rooms.',image='arrival',section='designs',kind='hero')
s('wellness','Warmth,\nafter the mountain.','OPTIONAL WELLNESS RETREAT','A quiet garden-level room of stone, timber and soft winter light. The illustrated €34,800 wellness suite is optional, including its €14,800 sauna package; it is unselected in the base budget.',image='spa',section='designs',kind='hero')
s('summer','Summer lives\nwith the doors open.','05 / THE SUMMER CHALET','Meadow greens, cool stone and the long light of the Alps. The reworked facade opens generously while retaining the familiar chalet silhouette and its relationship with the slope.',image='summer',section='seasons',kind='hero')
s('terrace','Take the slow\nway through the day.','THE SUMMER TERRACE','A sheltered place for coffee, reading and looking outward. The furniture and wind-screen treatment shown belong to the optional €12,600 terrace package.',image='terrace',section='seasons',kind='hero')
s('winter','A warm light\nin a white landscape.','THE WINTER CHALET','The same renovated chalet, held in snow and evening blue. Warm rooms glow behind the new glazing; timber and stone keep the building rooted in its Alpine setting.',image='winter',section='seasons',kind='hero')
s('seasonpair','One home.\nTwo beautiful worlds.','SUMMER / WINTER','Seasonal studies of the same proposed exterior. The architecture stays constant; light, landscape and daily rituals change around it.',section='seasons',kind='comparison')
s('comfort','Comfort begins\nwith the building.','FABRIC, AIR & LIGHT','Roof and envelope work, carefully specified glazing, and coordinated heating and ventilation support the architectural concept. Actual performance follows surveys, specialist design and commissioning.',section='delivery',kind='comfort')
s('investment','A clear view\nof the conversion.','06 / THE INVESTMENT','€687,500–€703,500 including a €62,000 client-held contingency. Furniture choices create the range. Optional wellness and terrace packages are excluded; concealed defects remain unpriced. Figures are fictional and include assumed VAT.',section='budget',kind='budget')
s('suppliers','Every package.\nEvery layer.','THE SUPPLIER STRUCTURE','Included subquotes explain their parent price. The electrical and heating packages sit inside building services, which sits inside the main conversion contract. Optional wellness remains separate.',section='budget',kind='hierarchy')
s('options','Make it\nyour mountain home.','OPTIONS & SELECTIONS','Base €687,500. Premium furniture adds €16,000; wellness adds €34,800; terrace living adds €12,600. All selections together: €750,900, including contingency and excluding unpriced concealed conditions.',section='budget',kind='options')
s('programme','A thoughtful\ntransformation.','07 / THE PROGRAMME','An indicative 40-week project, with work sequencing shaped by surveys, permissions, long-lead glazing and Alpine weather. No delivery date is guaranteed by this fictional programme.',section='delivery',kind='timeline')
s('scope','Before the\nfirst opening-up.','SCOPE & DECISIONS','Approve the design direction, investigate the actual building, resolve the technical design and select options before placing orders. A conversion begins with understanding what is already there.',section='delivery',kind='principles',points=['All clients, suppliers, quotations and prices are fictional','Before and proposed images are generated concept studies','Plans are unmeasured and not for construction','Surveys, fees, specialist reports and exceptional repairs are excluded'])
s('closing','Come for the mountains.\nStay for the feeling.','HAUS MORGENLICHT / DEMO 03','An old Austrian chalet, opened to a new way of living. Prepared for the fictional Leitner family by Morgenlicht Atelier.',image='winter',section='delivery',kind='cover')

