    if s['image']:
        pts='<ul>'+''.join(f'<li>{e(x)}</li>' for x in s['points'])+'</ul>' if s['points'] else ''
        return f'<div class="split-layout"><div class="copy">{head}{desc}{pts}</div>{img(s)}</div>'
    extra=''
    if s['points']:extra='<div class="points">'+''.join(f'<div><small>{n:02d}</small>{e(x)}</div>' for n,x in enumerate(s['points'],1))+'</div>'
    if kind=='comparison':
        pair={'exteriorcompare':[('before-exterior','IMAGINED ORIGINAL'),('summer','PROPOSED CONVERSION')],'interiorcompare':[('before-living','IMAGINED ORIGINAL'),('living','PROPOSED CONVERSION')],'seasonpair':[('summer','SUMMER / PROPOSED'),('winter','WINTER / SAME PROPOSAL')]}[s['key']]
        extra='<div class="diptych">'+''.join(f'<figure><img src="assets/{key}.webp" alt="{caption}"><figcaption>{caption}</figcaption></figure>' for key,caption in pair)+'</div>'
    if kind=='palette':extra='<div class="swatches">'+''.join(f'<div class="swatch" style="background:{c}">{label}<small>{c.upper()}</small></div>' for c,label in zip(manifest['theme']['colors'],['Snow linen','Glacier light','Pale fir','Mountain stone','Evening blue']))+'</div>'
    if kind=='details':extra='<table><tr><th>Material</th><th>Where it belongs</th><th>Design intent</th></tr>'+''.join(f'<tr><td>{e(r[1])}</td><td>{e(r[2])}</td><td>{e(r[3])}</td></tr>' for r in materials[:7])+'</table>'
    if kind=='budget':
        rs=[r for r in budget if not r['included'] and not r['optional'] and r['kind']!='unknown']
        extra='<table><tr><th>Package</th><th>Basis</th><th>Investment incl. assumed VAT</th></tr>'+''.join(f'<tr><td>{e(r["label"])}</td><td>{"Allowance" if r["kind"]=="estimate" else "Fictional quote"}</td><td>{money(r["amount"]) if r["amount"] is not None else money(r["min_amount"])+"–"+money(r["max_amount"])}</td></tr>' for r in rs)+'</table><div class="total"><span>Known conversion range</span><span>€687,500–€703,500</span></div>'
    if kind in ('options','comfort'):
        cards=[('Premium furniture','+ €16,000','A fuller specification of wool, rugs and loose furniture. Base allowance €42,000.'),('Wellness retreat','+ €34,800','Garden-level fit-out with included sauna package. Illustrated, unselected in the base.'),('Terrace living','+ €12,600','Outdoor lounge and wind-screen package. Additional to base works.')] if kind=='options' else [('Fabric','01','Renew roof layers and coordinate insulation, glazing and moisture strategy.'),('Fresh air','02','Resolve heating and ventilation together, with specialist design and commissioning.'),('Daylight','03','Open selected views and lighten interior surfaces, keeping the old roof and beams legible.')]
        extra='<div class="cards">'+''.join(f'<article class="card"><h3>{a}</h3><strong>{b}</strong><p>{c}</p></article>' for a,b,c in cards)+'</div>'
    if kind=='timeline':extra='<div class="timeline-grid">'+''.join(f'<article><small>{b}</small><h3>{c}</h3><p>{d}</p></article>' for a,b,c,d in programme)+'</div>'
    if kind=='hierarchy':extra='<div class="tree"><article><h3>Alpen Bauatelier / €248,000</h3><div class="child">Berg Struktur / €92,000 included</div><div class="child">Dach & Holz / €98,000 included</div><div class="child">Haus Technik / €58,000 included<div class="child">Lichtwerk Tirol / €24,000 included<br>Klima Berg / €34,000 included</div></div></article><article><h3>Panorama Werk / €104,000</h3><div class="child">Alpenglas / €64,000 included</div><br><h3>Optional wellness / €34,800</h3><div class="child">Sauna Form / €14,800 included</div><small>Parent package begins unselected. Included subquotes never increase the parent total.</small></article></div>'
    return f'<div class="inner">{head}{desc}{extra}</div>'
